targets.expr:
(
  sum(
    cantaloupe_audio_finops_run_ready{
      job="audio_finops_experiment"
    }
    and on(job, run_id)
    topk(
      1,
      push_time_seconds{job="audio_finops_experiment"}
    )
  )
  and on()
  (
    time() -
    max(push_time_seconds{job="audio_finops_experiment"})
    < 120
  )
) or vector(0)

max(
  keda_scaler_metrics_value{
    exported_namespace="apps",
    scaledObject="audio-transcode-burst",
    scaler="awsSqsQueueScaler",
    metric="s1-aws-sqs-cntlp-aws-queue-transcode"
  }
) or vector(0)

round(
  (
    (
      sum(
        sum_over_time(
          cantaloupe:container_allocated_cost_per_hour{
            namespace="apps",
            container=~"web|api|events|transcode"
          }[$__range:1m]
        )
      ) / 60
    )
    /
    sum(
      cantaloupe_audio_finops_run_ready{job="audio_finops_experiment"}
      and on(job, run_id)
      topk(
        1,
        push_time_seconds{job="audio_finops_experiment"}
          >= ${__from:date:seconds}
        and
        push_time_seconds{job="audio_finops_experiment"}
          <= ${__to:date:seconds}
      )
    )
  ) * 100000,
  0.01
)
and
(
  sum(
    cantaloupe_audio_finops_run_ready{job="audio_finops_experiment"}
    and on(job, run_id)
    topk(
      1,
      push_time_seconds{job="audio_finops_experiment"}
        >= ${__from:date:seconds}
      and
      push_time_seconds{job="audio_finops_experiment"}
        <= ${__to:date:seconds}
    )
  ) > 0
)

